class BigNumCalculator:
    """
    This is a class that implements big number calculations, including adding, subtracting and multiplying.
    """

    @staticmethod
    def add(num1, num2):
        """
        Adds two big numbers.
        :param num1: The first number to add,str.
        :param num2: The second number to add,str.
        :return: The sum of the two numbers,str.
        >>> bigNum = BigNumCalculator()
        >>> bigNum.add("12345678901234567890", "98765432109876543210")
        '111111111011111111100'

        """
        # Handle signs
        if num1.startswith('-') and num2.startswith('-'):
            return '-' + BigNumCalculator.add(num1[1:], num2[1:])
        elif num1.startswith('-'):
            return BigNumCalculator.subtract(num2, num1[1:])
        elif num2.startswith('-'):
            return BigNumCalculator.subtract(num1, num2[1:])

        # Both positive
        i = len(num1) - 1
        j = len(num2) - 1
        carry = 0
        result = []

        while i >= 0 or j >= 0 or carry:
            digit1 = int(num1[i]) if i >= 0 else 0
            digit2 = int(num2[j]) if j >= 0 else 0
            total = digit1 + digit2 + carry
            result.append(str(total % 10))
            carry = total // 10
            i -= 1
            j -= 1

        return ''.join(reversed(result))

    @staticmethod
    def subtract(num1, num2):
        """
        Subtracts two big numbers.
        :param num1: The first number to subtract,str.
        :param num2: The second number to subtract,str.
        :return: The difference of the two numbers,str.
        >>> bigNum = BigNumCalculator()
        >>> bigNum.subtract("12345678901234567890", "98765432109876543210")
        '-86419753208641975320'

        """
        # Handle signs
        if num1.startswith('-') and num2.startswith('-'):
            return BigNumCalculator.subtract(num2[1:], num1[1:])
        elif num1.startswith('-'):
            return '-' + BigNumCalculator.add(num1[1:], num2)
        elif num2.startswith('-'):
            return BigNumCalculator.add(num1, num2[1:])

        # Both positive
        # Determine which is larger
        if len(num1) < len(num2) or (len(num1) == len(num2) and num1 < num2):
            return '-' + BigNumCalculator.subtract(num2, num1)

        i = len(num1) - 1
        j = len(num2) - 1
        borrow = 0
        result = []

        while i >= 0:
            digit1 = int(num1[i]) - borrow
            digit2 = int(num2[j]) if j >= 0 else 0
            if digit1 < digit2:
                digit1 += 10
                borrow = 1
            else:
                borrow = 0
            result.append(str(digit1 - digit2))
            i -= 1
            j -= 1

        # Remove leading zeros
        while len(result) > 1 and result[-1] == '0':
            result.pop()

        return ''.join(reversed(result))

    @staticmethod
    def multiply(num1, num2):
        """
        Multiplies two big numbers.
        :param num1: The first number to multiply,str.
        :param num2: The second number to multiply,str.
        :return: The product of the two numbers,str.
        >>> bigNum = BigNumCalculator()
        >>> bigNum.multiply("12345678901234567890", "98765432109876543210")
        '1219326311370217952237463801111263526900'

        """
        # Handle signs
        if num1.startswith('-') and num2.startswith('-'):
            return BigNumCalculator.multiply(num1[1:], num2[1:])
        elif num1.startswith('-'):
            return '-' + BigNumCalculator.multiply(num1[1:], num2)
        elif num2.startswith('-'):
            return '-' + BigNumCalculator.multiply(num1, num2[1:])

        # Both positive
        if num1 == '0' or num2 == '0':
            return '0'

        result = [0] * (len(num1) + len(num2))

        for i in range(len(num1) - 1, -1, -1):
            carry = 0
            digit1 = int(num1[i])
            for j in range(len(num2) - 1, -1, -1):
                digit2 = int(num2[j])
                product = digit1 * digit2 + result[i + j + 1] + carry
                result[i + j + 1] = product % 10
                carry = product // 10
            result[i] += carry

        # Remove leading zeros
        while len(result) > 1 and result[0] == 0:
            result.pop(0)

        return ''.join(str(d) for d in result)

